//! Devtools window for the row store behind the details view.

use eframe::egui::{Context, DragValue, Grid, Id, RichText, ScrollArea, Sense, Shape, Stroke, Ui, Window, pos2, vec2};
use humansize::{BINARY, format_size};

use crate::icons::{self, svg};
use crate::ui::file_table::rows::{MemoryEstimate, Refresh, RefreshCounts, SelectionStats, SortSpec, Versions, ViewStats};
use crate::ui::file_table::table::columns::Col;

/// Rows generated by the synthetic data button unless changed.
pub const DEFAULT_SYNTHETIC_ROWS: usize = 100_000;

#[derive(Clone, Debug)]
pub struct Snapshot {
    pub owner: Id,
    pub label: String,
    pub mode: String,
    pub versions: Versions,
    pub store_len: usize,
    pub view_len: usize,
    pub view_revision: u64,
    pub stats: ViewStats,
    pub refresh_counts: RefreshCounts,
    pub last_refresh: Refresh,
    pub sort: SortSpec,
    pub selection_len: usize,
    pub selection_revision: u64,
    pub anchor: Option<String>,
    pub focus: Option<String>,
    pub preview: Option<String>,
    pub selection_stats: SelectionStats,
    pub memory: MemoryEstimate,
    pub view_bytes: usize,
    pub selection_bytes: usize,
    pub frame_ms: Vec<f32>,
    pub drawn_rows: usize,
    pub page_rows: usize,
    pub last_check: Option<Result<(), String>>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Command {
    CheckInvariants,
    Synthetic(usize),
    ClearRows,
    ResetFrameStats,
}

fn open_id() -> Id {
    Id::unique("ame_devtools_row_store_open")
}

fn snapshot_id() -> Id {
    Id::unique("ame_devtools_row_store_snapshot")
}

fn commands_id(owner: Id) -> Id {
    Id::unique(("ame_devtools_row_store_commands", owner))
}

fn count_id() -> Id {
    Id::unique("ame_devtools_row_store_count")
}

pub fn is_open(ctx: &Context) -> bool {
    ctx.data(|d| d.get_temp::<bool>(open_id())).unwrap_or(false)
}

pub fn set_open(ctx: &Context, open: bool) {
    ctx.data_mut(|d| d.insert_temp(open_id(), open));
}

pub fn toggle(ctx: &Context) {
    set_open(ctx, !is_open(ctx));
}

/// Makes `snapshot` the one the window shows.
pub fn publish(ctx: &Context, snapshot: Snapshot) {
    ctx.data_mut(|d| d.insert_temp(snapshot_id(), snapshot));
}

/// The snapshot of the explorer that drew last.
pub fn latest(ctx: &Context) -> Option<Snapshot> {
    ctx.data(|d| d.get_temp::<Snapshot>(snapshot_id()))
}

/// Queues `command` for the explorer identified by `owner`.
pub fn push_command(ctx: &Context, owner: Id, command: Command) {
    ctx.data_mut(|d| d.get_temp_mut_or_default::<Vec<Command>>(commands_id(owner)).push(command));
}

/// Takes the commands queued for `owner`.
pub fn take_commands(ctx: &Context, owner: Id) -> Vec<Command> {
    ctx.data_mut(|d| d.remove_temp::<Vec<Command>>(commands_id(owner))).unwrap_or_default()
}

/// Draws the window when open.
pub fn show(ctx: &Context) {
    let mut open = is_open(ctx);
    if !open {
        return;
    }
    Window::new("Devtools: Row store").open(&mut open).default_width(480.0).default_height(640.0).show(ctx, |ui| {
        ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| match latest(ctx) {
            Some(snapshot) => body(ui, &snapshot),
            None => {
                ui.weak("No explorer has drawn since the window opened.");
            }
        });
    });
    set_open(ctx, open);
}

fn mb(bytes: usize) -> String {
    format_size(bytes as u64, BINARY)
}

/// Mean, 95th percentile and maximum of `samples`.
pub fn frame_summary(samples: &[f32]) -> Option<(f32, f32, f32)> {
    if samples.is_empty() {
        return None;
    }
    let mut sorted = samples.to_vec();
    sorted.sort_by(f32::total_cmp);
    let mean = sorted.iter().sum::<f32>() / sorted.len() as f32;
    let p95 = sorted[((sorted.len() - 1) as f32 * 0.95) as usize];
    Some((mean, p95, *sorted.last().unwrap()))
}

fn sort_text(sort: &SortSpec) -> String {
    if sort.is_empty() {
        return "none (store order)".to_string();
    }
    let parts: Vec<String> = sort
        .keys()
        .iter()
        .map(|k| format!("{} {}", Col::from_id(k.column).map_or("?", |c| c.menu_name()), if k.descending { "descending" } else { "ascending" }))
        .collect();
    parts.join(", ")
}

fn body(ui: &mut Ui, s: &Snapshot) {
    ui.ctx().request_repaint_after(std::time::Duration::from_millis(250));
    ui.label(RichText::new(&s.label).weak());
    counts_section(ui, s);
    ui.separator();
    selection_section(ui, s);
    ui.separator();
    memory_section(ui, s);
    ui.separator();
    frame_section(ui, s);
    ui.separator();
    control_section(ui, s);
}

fn counts_section(ui: &mut Ui, s: &Snapshot) {
    icons::heading(ui, svg::STACK, "Rows");
    Grid::new("row_store_counts").num_columns(4).spacing([16.0, 3.0]).show(ui, |ui| {
        ui.label("Rows in store");
        ui.monospace(s.store_len.to_string());
        ui.label("Visible / hidden by filter");
        ui.monospace(format!("{} / {}", s.stats.visible, s.stats.hidden_by_filter));
        ui.end_row();
        ui.label("Images / videos");
        ui.monospace(format!("{} / {}", s.stats.images, s.stats.videos));
        ui.label("Folders / archives / other");
        ui.monospace(format!("{} / {} / {}", s.stats.dirs, s.stats.archives, s.stats.other));
        ui.end_row();
        ui.label("Total size");
        ui.monospace(mb(s.stats.total_size as usize));
        ui.label("Mode");
        ui.monospace(&s.mode);
        ui.end_row();
        ui.label("Store revision");
        ui.monospace(format!("{} (layout {}, edits {})", s.versions.revision, s.versions.layout, s.versions.edits));
        ui.label("View revision");
        ui.monospace(s.view_revision.to_string());
        ui.end_row();
        ui.label("Refreshes");
        ui.monospace(format!("{} unchanged, {} appended, {} rebuilt", s.refresh_counts.unchanged, s.refresh_counts.appended, s.refresh_counts.rebuilt));
        ui.label("Last refresh");
        ui.monospace(format!("{:?}", s.last_refresh));
        ui.end_row();
    });
    ui.horizontal_wrapped(|ui| {
        ui.label("Sort:");
        ui.monospace(sort_text(&s.sort));
    });
}

fn selection_section(ui: &mut Ui, s: &Snapshot) {
    icons::heading(ui, svg::LIST_CHECKS, "Selection");
    Grid::new("row_store_selection").num_columns(2).spacing([16.0, 3.0]).show(ui, |ui| {
        ui.label("Selected rows");
        ui.monospace(format!("{} (revision {})", s.selection_len, s.selection_revision));
        ui.end_row();
        ui.label("Counts");
        let c = &s.selection_stats;
        ui.monospace(format!("{} images, {} videos, {} folders, {} archives, {}", c.images, c.videos, c.dirs, c.archives, mb(c.size as usize)));
        ui.end_row();
        for (name, value) in [("Anchor", &s.anchor), ("Focus", &s.focus), ("Preview follows", &s.preview)] {
            ui.label(name);
            ui.monospace(value.as_deref().unwrap_or("-"));
            ui.end_row();
        }
    });
}

fn memory_section(ui: &mut Ui, s: &Snapshot) {
    icons::heading(ui, svg::MEMORY, "Memory estimate");
    let m = &s.memory;
    let total = m.total() + s.view_bytes + s.selection_bytes;
    Grid::new("row_store_memory").num_columns(4).spacing([16.0, 3.0]).show(ui, |ui| {
        ui.label("Row structs");
        ui.monospace(mb(m.row_inline));
        ui.label("Row strings and tags");
        ui.monospace(mb(m.row_heap));
        ui.end_row();
        ui.label("Keys");
        ui.monospace(mb(m.keys));
        ui.label("Key index");
        ui.monospace(mb(m.index));
        ui.end_row();
        ui.label("View index");
        ui.monospace(mb(s.view_bytes));
        ui.label("Selection");
        ui.monospace(mb(s.selection_bytes));
        ui.end_row();
    });
    let per_row = if s.store_len == 0 { 0 } else { total / s.store_len };
    ui.label(format!("Total {} ({} per row)", mb(total), mb(per_row)));
}

fn frame_section(ui: &mut Ui, s: &Snapshot) {
    icons::heading(ui, svg::GAUGE, "Details view frame time");
    match frame_summary(&s.frame_ms) {
        Some((mean, p95, max)) => {
            ui.label(format!("mean {mean:.2} ms, p95 {p95:.2} ms, max {max:.2} ms over {} frames", s.frame_ms.len()));
            sparkline(ui, &s.frame_ms);
        }
        None => {
            ui.weak("no frames recorded");
        }
    }
    ui.label(format!("{} rows laid out of {} visible ({} fit the window)", s.drawn_rows, s.view_len, s.page_rows));
}

pub fn sparkline(ui: &mut Ui, series: &[f32]) {
    let width = ui.available_width().max(120.0);
    let (rect, _) = ui.allocate_exact_size(vec2(width, 48.0), Sense::hover());
    let painter = ui.painter_at(rect);
    painter.rect_stroke(rect, 2.0, ui.visuals().widgets.noninteractive.bg_stroke, egui::StrokeKind::Inside);
    if series.len() < 2 {
        return;
    }
    let top = series.iter().copied().fold(1.0f32, f32::max) * 1.25;
    let step = rect.width() / (series.len() - 1) as f32;
    let points: Vec<_> = series.iter().enumerate().map(|(i, v)| pos2(rect.left() + step * i as f32, rect.bottom() - (v / top).clamp(0.0, 1.0) * rect.height())).collect();
    painter.add(Shape::line(points, Stroke::new(1.5, crate::theme::info(ui))));
}

fn control_section(ui: &mut Ui, s: &Snapshot) {
    icons::heading(ui, svg::SLIDERS, "Controls");
    let ctx = ui.ctx().clone();
    ui.horizontal_wrapped(|ui| {
        if icons::button(ui, svg::CHECK_CIRCLE, "Check invariants").on_hover_text("Compare the store, the view and the selection against fresh computations").clicked() {
            push_command(&ctx, s.owner, Command::CheckInvariants);
        }
        if icons::button(ui, svg::ARROW_COUNTER_CLOCKWISE, "Reset frame stats").clicked() {
            push_command(&ctx, s.owner, Command::ResetFrameStats);
        }
    });
    match &s.last_check {
        Some(Ok(())) => {
            ui.colored_label(crate::theme::success(ui), "Invariants hold");
        }
        Some(Err(e)) => {
            ui.colored_label(crate::theme::error(ui), format!("Violated: {e}"));
        }
        None => {
            ui.weak("Not checked yet");
        }
    }
    let mut count = ctx.data(|d| d.get_temp::<usize>(count_id())).unwrap_or(DEFAULT_SYNTHETIC_ROWS);
    ui.horizontal_wrapped(|ui| {
        if ui.add(DragValue::new(&mut count).range(0..=2_000_000).speed(1000).suffix(" rows")).changed() {
            ctx.data_mut(|d| d.insert_temp(count_id(), count));
        }
        if icons::button(ui, svg::DATABASE, "Replace with synthetic rows").on_hover_text("Replaces this tab's rows with generated ones to profile the details view").clicked() {
            push_command(&ctx, s.owner, Command::Synthetic(count));
        }
        if crate::ui::danger_icon_button(ui, svg::TRASH, "Clear rows").clicked() {
            push_command(&ctx, s.owner, Command::ClearRows);
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn frame_summary_reports_mean_p95_and_max() {
        assert_eq!(frame_summary(&[]), None);
        let samples: Vec<f32> = (1..=100).map(|v| v as f32).collect();
        let (mean, p95, max) = frame_summary(&samples).unwrap();
        assert!((mean - 50.5).abs() < 1e-3);
        assert_eq!(p95, 95.0);
        assert_eq!(max, 100.0);
        assert_eq!(frame_summary(&[2.5]).unwrap(), (2.5, 2.5, 2.5));
    }

    #[test]
    fn sort_text_names_columns_and_directions() {
        assert!(sort_text(&SortSpec::new()).contains("none"));
        let mut spec = SortSpec::new();
        spec.click(Col::Size.id(), false);
        spec.click(Col::Name.id(), true);
        spec.click(Col::Name.id(), true);
        assert_eq!(sort_text(&spec), "Size ascending, Name descending");
    }

    #[test]
    fn commands_are_delivered_once_to_their_owner() {
        let ctx = Context::default();
        let (a, b) = (Id::unique("a"), Id::unique("b"));
        push_command(&ctx, a, Command::CheckInvariants);
        push_command(&ctx, a, Command::Synthetic(5));
        push_command(&ctx, b, Command::ClearRows);
        assert_eq!(take_commands(&ctx, a), [Command::CheckInvariants, Command::Synthetic(5)]);
        assert!(take_commands(&ctx, a).is_empty());
        assert_eq!(take_commands(&ctx, b), [Command::ClearRows]);
    }

    #[test]
    fn the_window_toggles_and_shows_without_a_snapshot() {
        let ctx = Context::default();
        assert!(!is_open(&ctx));
        toggle(&ctx);
        assert!(is_open(&ctx));
        let input = egui::RawInput { screen_rect: Some(egui::Rect::from_min_size(pos2(0.0, 0.0), vec2(900.0, 900.0))), ..Default::default() };
        ctx.run_ui(input, |ui| {
            egui::CentralPanel::default().show(ui, |_| {});
            show(ui.ctx());
        })
        .drop_without_applying_deltas();
        toggle(&ctx);
        assert!(!is_open(&ctx));
    }
}
